(0, import_node_test.default)("MultiPolygon parts and courtyard holes are rasterised and deduplicated", () => {
  const source = buildingDraft([
    { x: 0, y: 0, z: 0 },
    { x: 5, y: 0, z: 0 }
  ], 5);
  const draft = {
    ...source,
    footprint: {
      type: "MultiPolygon",
      coordinateSpace: "world-cell-xz",
      coordinates: [
        [
          [[0, 0], [5, 0], [5, 5], [0, 5], [0, 0]],
          [[2, 2], [3, 2], [3, 3], [2, 3], [2, 2]]
        ],
        [
          [[10, 0], [12, 0], [12, 2], [10, 2], [10, 0]]
        ],
        // This overlapping part deliberately exercises cross-polygon dedupe.
        [
          [[10, 0], [12, 0], [12, 2], [10, 2], [10, 0]]
        ]
      ]
    }
  };
  const geometry = buildLineBrushBuildingGeometry({ draft, baseY: 0, storeyCount: 1 });
  const footprint = new Set(geometry.footprintCells.map(cellKey));
  const exterior = new Set(geometry.exteriorFootprintCells.map(cellKey));
  import_strict.default.equal(geometry.footprintCells.length, 28);
  import_strict.default.equal(footprint.has("2::2"), false, "the courtyard remains empty");
  import_strict.default.equal(footprint.has("10::0"), true, "the second MultiPolygon part is retained");
  import_strict.default.equal(exterior.size, 24);
  for (const key of ["1::2", "3::2", "2::1", "2::3"]) {
    import_strict.default.equal(exterior.has(key), true, `${key} is an editable courtyard exterior wall`);
  }
  import_strict.default.equal(geometry.occupiedCells.length, 76);
  assertUniqueCells(geometry.occupiedCells);
});
